const listChannelMessages = `-- name: ListChannelMessages :many
SELECT
  m.id,
  m.organization_id,
  m.channel_id,
  m.message_text,
  m.author_employee_id,
  m.parent_message_id,
  m.is_deleted,
  m.is_edited,
  m.file_ids,
  m.message_kind,
  m.system_event_type,
  m.metadata,
  m.updated_at,
  (e.given_name || ' ' || e.family_name)::text AS author_name,
  e.id::text AS author_email,
  (
    SELECT COUNT(*)
    FROM chat.message replies
    WHERE replies.parent_message_id = m.id
      AND replies.organization_id = m.organization_id
  ) AS reply_count,
  (
    SELECT COALESCE(array_agg(DISTINCT replies.author_employee_id ORDER BY replies.author_employee_id), ARRAY[]::uuid[])
    FROM chat.message replies
    WHERE replies.parent_message_id = m.id
      AND replies.organization_id = m.organization_id
  )::uuid[] AS thread_participant_ids,
  (
    SELECT MAX(replies.updated_at)
    FROM chat.message replies
    WHERE replies.parent_message_id = m.id
      AND replies.organization_id = m.organization_id
  )::timestamptz AS last_reply_at,
  (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'emoji_code', agg.emoji_code,
        'count', agg.count,
        'employee_ids', agg.employee_ids,
        'first_reacted_at', agg.first_reacted_at
      )
      ORDER BY agg.count DESC, agg.emoji_code
    ), '[]'::jsonb)
    FROM (
      SELECT
        r.emoji_code,
        COUNT(*) AS count,
        array_agg(r.employee_id ORDER BY r.employee_id) AS employee_ids,
        MIN(r.updated_at) AS first_reacted_at
      FROM chat.reaction r
      WHERE r.message_id = m.id
        AND r.organization_id = m.organization_id
      GROUP BY r.emoji_code
    ) agg
  )::jsonb AS reactions_json
FROM
  chat.message m
  INNER JOIN organization.employee e ON (m.organization_id, m.author_employee_id) = (e.organization_id, e.id)
WHERE
  m.channel_id = $1
  AND m.organization_id = $2
  AND m.parent_message_id IS NULL -- Only top-level messages
  AND m.is_deleted = FALSE
  AND ($3::uuid IS NULL
    OR m.id < $3::uuid) -- UUID v7 cursor (time-sortable, stable ordering)
ORDER BY
  m.id DESC
LIMIT $4
`

type ListChannelMessagesParams struct {
	ChannelID      dbuuid.UUID     `json:"channel_id"`
	OrganizationID dbuuid.UUID     `json:"organization_id"`
	CursorID       dbuuid.NullUUID `json:"cursor_id"`
	Limit          int32           `json:"limit"`
}

type ListChannelMessagesRow struct {
	ID                   dbuuid.UUID        `json:"id"`
	OrganizationID       dbuuid.UUID        `json:"organization_id"`
	ChannelID            dbuuid.UUID        `json:"channel_id"`
	MessageText          string             `json:"message_text"`
	AuthorEmployeeID     dbuuid.UUID        `json:"author_employee_id"`
	ParentMessageID      dbuuid.NullUUID    `json:"parent_message_id"`
	IsDeleted            bool               `json:"is_deleted"`
	IsEdited             bool               `json:"is_edited"`
	FileIds              []dbuuid.UUID      `json:"file_ids"`
	MessageKind          string             `json:"message_kind"`
	SystemEventType      pgtype.Text        `json:"system_event_type"`
	Metadata             []byte             `json:"metadata"`
	UpdatedAt            pgtype.Timestamptz `json:"updated_at"`
	AuthorName           string             `json:"author_name"`
	AuthorEmail          string             `json:"author_email"`
	ReplyCount           int64              `json:"reply_count"`
	ThreadParticipantIds []dbuuid.UUID      `json:"thread_participant_ids"`
	LastReplyAt          pgtype.Timestamptz `json:"last_reply_at"`
	ReactionsJson        []byte             `json:"reactions_json"`
}

// Lists messages in a channel with cursor-based pagination (ordered by id DESC for loading newest first).
// Uses UUID v7 as cursor: id encodes creation timestamp, enabling time-based pagination without separate timestamp column.
// When no cursor: returns most recent messages (newest first).
// When cursor provided: returns older messages (before cursor id).
// Frontend reverses the array to display oldest-to-newest (chat UX: newest at bottom).
// Includes thread reply metadata and aggregated reactions for initial render.
func (q *Queries) ListChannelMessages(ctx context.Context, db DBTX, arg *ListChannelMessagesParams) ([]*ListChannelMessagesRow, error) {
	rows, err := db.Query(ctx, listChannelMessages,
		arg.ChannelID,
		arg.OrganizationID,
		arg.CursorID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ListChannelMessagesRow
	for rows.Next() {
		var i ListChannelMessagesRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.ChannelID,
			&i.MessageText,
			&i.AuthorEmployeeID,
			&i.ParentMessageID,
			&i.IsDeleted,
			&i.IsEdited,
			&i.FileIds,
			&i.MessageKind,
			&i.SystemEventType,
			&i.Metadata,
			&i.UpdatedAt,
			&i.AuthorName,
			&i.AuthorEmail,
			&i.ReplyCount,
			&i.ThreadParticipantIds,
			&i.LastReplyAt,
			&i.ReactionsJson,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

