const searchChannels = `-- name: SearchChannels :many
WITH search_config AS (
  SELECT
    set_limit(0.3) -- Lower threshold for short queries
)
SELECT
  c.id,
  c.organization_id,
  c.title_slug,
  c.display_name,
  c.description,
  c.channel_type,
  c.is_private,
  c.updated_at,
  similarity(c.display_name, $1) AS relevance_score
FROM
  chat.channel c
  CROSS JOIN search_config
WHERE
  c.organization_id = $2
  AND c.is_archived = FALSE
  AND c.display_name % $1
  AND ( -- Permission filtering: public channels OR user is member
    c.is_private = FALSE
    OR EXISTS (
      SELECT
        1
      FROM
        chat.channel_membership cm
      WHERE
        cm.channel_id = c.id
        AND cm.employee_id = $3
        AND cm.organization_id = c.organization_id))
  AND ($4::uuid IS NULL
    OR c.id < $4::uuid)
ORDER BY
  relevance_score DESC,
  c.updated_at DESC,
  c.id DESC
LIMIT $5::int
`

type SearchChannelsParams struct {
	QueryText      string          `json:"query_text"`
	OrganizationID dbuuid.UUID     `json:"organization_id"`
	EmployeeID     dbuuid.UUID     `json:"employee_id"`
	Cursor         dbuuid.NullUUID `json:"cursor"`
	Limit          int32           `json:"limit"`
}

type SearchChannelsRow struct {
	ID             dbuuid.UUID        `json:"id"`
	OrganizationID dbuuid.UUID        `json:"organization_id"`
	TitleSlug      string             `json:"title_slug"`
	DisplayName    string             `json:"display_name"`
	Description    pgtype.Text        `json:"description"`
	ChannelType    string             `json:"channel_type"`
	IsPrivate      bool               `json:"is_private"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
	RelevanceScore float32            `json:"relevance_score"`
}

// =============================================================================
// SEARCH QUERIES (Multilingual Fuzzy Search with pg_trgm)
// =============================================================================
// Fuzzy search for channels by display_name and description with permission filtering.
// Returns only channels the employee can access (public or member of private).
// Uses lower similarity threshold (0.3) for better matching on short queries.
func (q *Queries) SearchChannels(ctx context.Context, db DBTX, arg *SearchChannelsParams) ([]*SearchChannelsRow, error) {
	rows, err := db.Query(ctx, searchChannels,
		arg.QueryText,
		arg.OrganizationID,
		arg.EmployeeID,
		arg.Cursor,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*SearchChannelsRow
	for rows.Next() {
		var i SearchChannelsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.TitleSlug,
			&i.DisplayName,
			&i.Description,
			&i.ChannelType,
			&i.IsPrivate,
			&i.UpdatedAt,
			&i.RelevanceScore,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchMessages = `-- name: SearchMessages :many
SELECT
  m.id,
  m.organization_id,
  m.channel_id,
  m.message_text,
  m.author_employee_id,
  m.parent_message_id,
  m.is_edited,
  m.file_ids,
  m.updated_at, -- PGroonga relevance score (higher = better match)
  pgroonga_score(m.tableoid, m.ctid)::real AS relevance_score, -- Highlighted snippet with <mark> tags (PGroonga default)
  pgroonga_snippet_html(m.message_text, pgroonga_query_extract_keywords($1)) AS highlighted_snippet, -- Channel context for display
  c.display_name AS channel_name,
  c.is_private AS channel_is_private
FROM
  chat.message m
  INNER JOIN chat.channel c ON (m.organization_id, m.channel_id) = (c.organization_id, c.id)
WHERE
  m.organization_id = $2
  AND m.is_deleted = FALSE -- PGroonga full-text search (supports all languages automatically)
  AND m.message_text &@~ $1 -- Permission filtering: public channels OR member of private channel
    AND (c.is_private = FALSE
      OR EXISTS (
        SELECT
          1
        FROM
          chat.channel_membership cm
        WHERE
          cm.channel_id = c.id
          AND cm.employee_id = $3
          AND cm.organization_id = m.organization_id)) -- Cursor pagination using UUID v7
    AND ($4::uuid IS NULL
      OR m.id < $4::uuid)
  ORDER BY
    relevance_score DESC,
    m.updated_at DESC,
    m.id DESC
  LIMIT $5::int
`

type SearchMessagesParams struct {
	QueryText      interface{}     `json:"query_text"`
	OrganizationID dbuuid.UUID     `json:"organization_id"`
	EmployeeID     dbuuid.UUID     `json:"employee_id"`
	Cursor         dbuuid.NullUUID `json:"cursor"`
	Limit          int32           `json:"limit"`
}

type SearchMessagesRow struct {
	ID                 dbuuid.UUID        `json:"id"`
	OrganizationID     dbuuid.UUID        `json:"organization_id"`
	ChannelID          dbuuid.UUID        `json:"channel_id"`
	MessageText        string             `json:"message_text"`
	AuthorEmployeeID   dbuuid.UUID        `json:"author_employee_id"`
	ParentMessageID    dbuuid.NullUUID    `json:"parent_message_id"`
	IsEdited           bool               `json:"is_edited"`
	FileIds            []dbuuid.UUID      `json:"file_ids"`
	UpdatedAt          pgtype.Timestamptz `json:"updated_at"`
	RelevanceScore     float32            `json:"relevance_score"`
	HighlightedSnippet interface{}        `json:"highlighted_snippet"`
	ChannelName        string             `json:"channel_name"`
	ChannelIsPrivate   bool               `json:"channel_is_private"`
}

// Multilingual full-text search using PGroonga with automatic language detection.
// Returns ranked results with highlighted snippets and channel context.
// Permission filtering: Only returns messages from channels the employee can access.
//
// APPROACH:
// - Uses PGroonga's &@~ operator for full-text search across all languages
// - Automatic tokenization for CJK (Chinese, Japanese, Korean) and Latin scripts
// - Built-in relevance scoring via pgroonga_score()
// - Native snippet generation with pgroonga_snippet_html()
//
// INDEX USAGE:
// - Requires PGroonga index: idx_message_pgroonga_search (see migration below)
// - Single index handles all languages efficiently
// - No need for separate FTS and trigram indexes
//
// PERFORMANCE:
// - Faster than pg_trgm for CJK languages
// - Comparable to tsvector for Latin scripts
// - Unified index reduces storage overhead
func (q *Queries) SearchMessages(ctx context.Context, db DBTX, arg *SearchMessagesParams) ([]*SearchMessagesRow, error) {
	rows, err := db.Query(ctx, searchMessages,
		arg.QueryText,
		arg.OrganizationID,
		arg.EmployeeID,
		arg.Cursor,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*SearchMessagesRow
	for rows.Next() {
		var i SearchMessagesRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.ChannelID,
			&i.MessageText,
			&i.AuthorEmployeeID,
			&i.ParentMessageID,
			&i.IsEdited,
			&i.FileIds,
			&i.UpdatedAt,
			&i.RelevanceScore,
			&i.HighlightedSnippet,
			&i.ChannelName,
			&i.ChannelIsPrivate,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

